importScripts('./augment-sim.js');
let batch=null,running=false,serial=0,lastSnapshot=0,page=0,viewSort='retained',viewSkill=-1,viewSkillMetric='final',started=0,elapsedMs=0;
function publish(type){if(!batch)return;const {rows,...rest}=batch.snapshot();if(viewSort==='frequency')rows.sort((a,b)=>b.count-a.count||ForgeAugmentSim.compare(a,b,batch.config.sort,batch.config.sortSkill,batch.config.sortSkillMetric));else if(viewSort!=='retained')rows.sort((a,b)=>ForgeAugmentSim.compare(a,b,viewSort,viewSkill,viewSkillMetric));if(running||type==='done'||type==='stopped')elapsedMs=Date.now()-started;page=Math.max(0,Math.min(Math.max(0,Math.ceil(rows.length/25)-1),page));postMessage({type,...rest,elapsedMs,viewSort,viewSkill,viewSkillMetric,total:rows.length,page,rows:rows.slice(page*25,page*25+25)});lastSnapshot=Date.now();}
function tick(id){if(id!==serial||!running||!batch)return;try{const start=Date.now();let done=false;do{done=batch.step(100);}while(!done&&Date.now()-start<30);if(done){running=false;publish('done');}else{if(Date.now()-lastSnapshot>=500)publish('progress');setTimeout(()=>tick(id),0);}}catch(e){running=false;postMessage({type:'error',message:e.message});}}
self.onmessage=event=>{const m=event.data;try{if(m.type==='start'){serial++;page=0;viewSort='retained';batch=ForgeAugmentSim.createBatch(m.data,m.config);running=true;started=lastSnapshot=Date.now();tick(serial);}else if(m.type==='stop'){running=false;serial++;publish('stopped');}else if(m.type==='page'&&batch){const skill=Number(m.skill??viewSkill),metric=m.skillMetric||viewSkillMetric,sort=m.sort||viewSort;if(sort.startsWith('specificSkill')&&(!batch.ctx.skills.has(skill)||!['final','added'].includes(metric))){postMessage({type:'viewError',message:'请选择有效的排序技能和统计口径'});return;}page=Number.isInteger(m.page)?m.page:0;viewSort=sort;viewSkill=skill;viewSkillMetric=metric;publish('page');}else if(m.type==='clear'){running=false;serial++;batch=null;}}catch(e){running=false;postMessage({type:'error',message:e.message});}};
